                    $columns=['customer_id']; $values=[$cid?:null]; foreach($row as $header=>$value){$column=$mapping[$header]; if($column==='customer_name')continue; $columns[]=$column; $values[]=trim((string)$value);} $columns[]='created_by';$columns[]='updated_by';$values[]=$userId;$values[]=$userId;
